parameters.jsCode:
const items = $input.all();
const webhookData = $('Webhook').first().json;
const visionData = $('OpenAI Vision Embed').first().json;

const results = items.map(item => {
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          model: 'gpt-4o-mini + text-embedding-3-small'
        }
      }
    };
  }

  try {
    // Parse vision analysis
    let analysis = {};
    try {
      analysis = JSON.parse(visionData.choices?.[0]?.message?.content || '{}');
    } catch (e) {
      analysis = { description: visionData.choices?.[0]?.message?.content || '' };
    }

    // Get embedding
    const embedding = item.json.data?.[0]?.embedding || [];

    return {
      json: {
        success: true,
        data: {
          embedding: embedding,
          dimensions: embedding.length,
          analysis: {
            description: analysis.description || '',
            objects: analysis.objects || [],
            scene: analysis.scene || '',
            colors: analysis.colors || [],
            mood: analysis.mood || '',
            tags: analysis.tags || [],
            style: analysis.style || ''
          }
        },
        meta: {
          provider: 'openai',
          vision_model: 'gpt-4o-mini',
          embedding_model: 'text-embedding-3-small'
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to process image: ' + e.message,
          status: 'PROCESS_ERROR'
        },
        meta: {
          provider: 'openai'
        }
      }
    };
  }
});

return results;
